const RELIC_BY_ID={};RELIC_CATALOG.forEach(it=>{it.img="relic_"+it.id+".png";RELIC_BY_ID[it.id]=it});
const RELIC_POOL={};["common","rare","epic","legendary"].forEach(t=>{RELIC_POOL[t]=RELIC_CATALOG.filter(it=>it.tier===t)});
function relicById(id){return RELIC_BY_ID[id]||null}
function relicName(it){return dc(it.zh,it.en)}
function relicTierLabel(t){const m=RELIC_TIERS[t];return m?dc(m.zh,m.en):t}
function relicKindLabel(k){return"relic"===k?dc("遺物","Relic"):dc("古董","Antique")}
function relicImgUrl(it){return it?RELIC_IMG_DIR+(it.img||it.id+".png"):null}
function relicImgFail(el){const ex=["png","jpg","jpeg","webp"],n=+(el.dataset.n||0)+1;if(n<ex.length&&!el.dataset.custom){el.dataset.n=n;el.src=el.src.replace(/\.[a-z]+$/i,"."+ex[n]);return}el.style.display="none";const sp=el.nextElementSibling;sp&&(sp.style.display="flex")}
window.relicImgFail=relicImgFail;

/* ---------- 設定 ---------- */
function relicMerge(base,src){const out=Array.isArray(base)?base.slice():{...base};if(src&&"object"==typeof src&&!Array.isArray(src))for(const k of Object.keys(src)){const bv=base?base[k]:void 0,sv=src[k];out[k]=bv&&"object"==typeof bv&&!Array.isArray(bv)&&sv&&"object"==typeof sv&&!Array.isArray(sv)?relicMerge(bv,sv):sv}return out}
let RELIC_CFG=relicMerge(RELIC_DEFAULTS,{}),RELIC_CFG_AT=0,RELIC_CFG_LOADED=!1;
function relicCfg(){return RELIC_CFG}
async function relicEnsureConfig(force){if(!force&&RELIC_CFG_LOADED&&Date.now()-RELIC_CFG_AT<3e5)return RELIC_CFG;try{const row=await RKV.get("config:relic_settings");RELIC_CFG=relicMerge(RELIC_DEFAULTS,row?JSON.parse(row.value):{});RELIC_CFG_LOADED=!0}catch(_){RELIC_CFG_LOADED||(RELIC_CFG=relicMerge(RELIC_DEFAULTS,{}))}RELIC_CFG_AT=Date.now();return RELIC_CFG}
async function relicSaveConfig(cfg){await RKV.set("config:relic_settings",JSON.stringify(cfg));RELIC_CFG=relicMerge(RELIC_DEFAULTS,cfg);RELIC_CFG_LOADED=!0;RELIC_CFG_AT=Date.now()}
function relicVisible(){return!!RELIC_CFG.enabled||Yg()}

/* ---------- 時間（一律 UTC+8，沿用 hs/ys/fs） ---------- */
function relicParseTime(s,allow24){const m=/^(\d{1,2}):(\d{2})$/.exec(String(s==null?"":s).trim());if(!m)return null;const h=+m[1],mi=+m[2];if(mi>59)return null;if(24===h&&0===mi&&allow24)return 1440;if(h>23)return null;return 60*h+mi}
function relicTimeStr(min){if(1440===min)return"24:00";return String(Math.floor(min/60)).padStart(2,"0")+":"+String(min%60).padStart(2,"0")}
function relicDayParts(day){const p=String(day).split("-").map(Number);return{y:p[0],m:p[1],d:p[2]}}
function relicDayTs(day,min){const p=relicDayParts(day);return Date.UTC(p.y,p.m-1,p.d,0,0,0)-288e5+6e4*(min||0)}
function relicAddDays(day,k){return ys(relicDayTs(day,720)+864e5*k)}
function relicSessionsFor(day,cfg){cfg=cfg||RELIC_CFG;const out=[],ss=Array.isArray(cfg.sessions)?cfg.sessions:[];if(ss.length&&(!cfg.sessionsFrom||relicDayTs(day,0)>=relicDayTs(cfg.sessionsFrom,0)))ss.forEach((x,i)=>{const d=relicParseTime(x&&x.start);if(null==d)return;let e=null;if(1){const L=(cfg.live||{}),need=(3+relicExtrasFor(day,d,cfg).length)*(Math.max(30,+L.capSec||180)+Math.max(5,+L.gapSec||20));e=d+Math.ceil(need/60)+1}e>d&&!out.some(z=>z.idx===d)&&out.push({idx:d,dm:d,em:e})});out.sort((x,y)=>x.dm-y.dm||x.idx-y.idx);return out}
function relicSessSorter(day,cfg){const SS=relicSessionsFor(day,cfg),o=r=>{const S=SS.find(z=>z.idx===(r.relicSess||0));return S?S.dm:9999+(r.relicSess||0)};return(x,y)=>o(x)-o(y)||(x.slot||0)-(y.slot||0)}
function relicSessNeed(S,cfg){cfg=cfg||RELIC_CFG;return Math.min(60,Math.floor((S.em-S.dm)/2))}